using System.IO;
using System.Reflection;
using UnityEngine;

namespace HatterCartsPack
{
    /// <summary>Loads the sprites embedded in the DLL (generated by tools/make_sprites.py).</summary>
    internal static class OrbCartAssets
    {
        private static Sprite icon;
        private static Texture2D emblem;

        internal static Sprite Icon
        {
            get
            {
                if (icon != null) return icon;
                Texture2D tex = Load("icon.png", mipmaps: false);
                if (tex == null) return null;
                icon = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
                icon.name = "Orb Cart Icon";
                return icon;
            }
        }

        internal static Texture2D Emblem => emblem != null ? emblem : (emblem = Load("emblem.png", mipmaps: true));

        // Icon overlay (512x512, readable); only needed while composing the icon at startup.
        internal static Texture2D HatchOverlay => Load("hatch_overlay.png", mipmaps: false);

        private static Texture2D Load(string file, bool mipmaps)
        {
            string resource = "HatterCartsPack.Assets.orb_cart_" + file;
            using (Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resource))
            {
                if (stream == null)
                {
                    Plugin.Log.LogWarning($"Embedded asset '{resource}' is missing.");
                    return null;
                }

                byte[] bytes = new byte[stream.Length];
                int read = 0;
                while (read < bytes.Length)
                {
                    int n = stream.Read(bytes, read, bytes.Length - read);
                    if (n <= 0) break;
                    read += n;
                }

                Texture2D tex = new Texture2D(2, 2, TextureFormat.RGBA32, mipmaps)
                {
                    name = Path.GetFileNameWithoutExtension(file),
                    wrapMode = TextureWrapMode.Clamp,
                    filterMode = FilterMode.Bilinear,
                    hideFlags = HideFlags.DontUnloadUnusedAsset
                };
                if (!tex.LoadImage(bytes))
                {
                    Plugin.Log.LogWarning($"Could not decode embedded asset '{resource}'.");
                    return null;
                }
                return tex;
            }
        }
    }
}
